using System;
using System.Linq;
namespace AfterHours {public partial class MainWindow {
 string SeatPosition(int id,J hand){int count=Session["players"].Items.Count();var ids=Session["players"].Items.Where(p=>p["status"].S!="empty"&&p["status"].S!="busted").Select(p=>p["id"].I).OrderBy(x=>(hand["button"].I-x+count)%count).ToArray();int offset=Array.IndexOf(ids,id);string[] codes=ids.Length>=7?new[]{"BTN","SB","BB","UTG","MP","HJ","CO"}:ids.Length==6?new[]{"BTN","SB","BB","UTG","HJ","CO"}:ids.Length==5?new[]{"BTN","SB","BB","UTG","CO"}:ids.Length==4?new[]{"BTN","SB","BB","CO"}:ids.Length==3?new[]{"BTN","SB","BB"}:new[]{"BTN/SB","BB"};string[] names=ids.Length>=7?new[]{"庄家位","小盲位","大盲位","枪口位","中位","劫持位","关煞位"}:ids.Length==6?new[]{"庄家位","小盲位","大盲位","枪口位","劫持位","关煞位"}:ids.Length==5?new[]{"庄家位","小盲位","大盲位","枪口位","关煞位"}:ids.Length==4?new[]{"庄家位","小盲位","大盲位","关煞位"}:ids.Length==3?new[]{"庄家位","小盲位","大盲位"}:new[]{"庄家/小盲位","大盲位"};return offset>=0&&offset<codes.Length?"["+codes[offset]+"]"+names[offset]:"空座";}
}}
